import{_ as t,o as a,c as o,a5 as s}from"./chunks/framework.DxOcC6on.js";const g=JSON.parse('{"title":"GitLab Integration","description":"Connect Matrix rooms to GitLab projects for merge request, issue, push, and release notifications","frontmatter":{"title":"GitLab Integration","description":"Connect Matrix rooms to GitLab projects for merge request, issue, push, and release notifications","audience":["user","operator","developer"],"integration":"gitlab","status":"current"},"headers":[],"relativePath":"integrations/gitlab.md","filePath":"integrations/gitlab.md","lastUpdated":1775244648000}'),i={name:"integrations/gitlab.md"};function d(n,e,r,l,c,h){return a(),o("div",null,[...e[0]||(e[0]=[s(`<h1 id="gitlab" tabindex="-1">GitLab <a class="header-anchor" href="#gitlab" aria-label="Permalink to &quot;GitLab&quot;">​</a></h1><p>Hookshot connects Matrix rooms to GitLab projects. It delivers notifications for merge requests, issues, pushes, tags, wiki changes, and releases. It accepts bot commands to create and close issues.</p><h2 id="connection-types" tabindex="-1">Connection types <a class="header-anchor" href="#connection-types" aria-label="Permalink to &quot;Connection types&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Type</th><th>State event</th><th>Purpose</th></tr></thead><tbody><tr><td>Repository</td><td><code>uk.half-shot.matrix-hookshot.gitlab.repository</code></td><td>Monitor project events, run commands</td></tr><tr><td>Issue</td><td><code>uk.half-shot.matrix-hookshot.gitlab.issue</code></td><td>Bridge a single issue to a dedicated room</td></tr></tbody></table><h2 id="capabilities" tabindex="-1">Capabilities <a class="header-anchor" href="#capabilities" aria-label="Permalink to &quot;Capabilities&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Capability</th><th>Supported</th></tr></thead><tbody><tr><td>Receive events in Matrix</td><td>Yes — 12 event handler bindings</td></tr><tr><td>Send commands from Matrix</td><td>Yes — 3 commands</td></tr><tr><td>OAuth</td><td>Token-based (personal access tokens)</td></tr><tr><td>Webhook-based</td><td>Yes</td></tr><tr><td>Bot commands</td><td><code>!gl</code> prefix</td></tr><tr><td>Widget UI</td><td>Yes</td></tr><tr><td>Provisioning API</td><td>Yes</td></tr><tr><td>GitLab.com + self-hosted</td><td>Yes — multiple instances supported</td></tr></tbody></table><h2 id="supported-events" tabindex="-1">Supported events <a class="header-anchor" href="#supported-events" aria-label="Permalink to &quot;Supported events&quot;">​</a></h2><table tabindex="0"><thead><tr><th>GitLab event</th><th>Handler</th><th>Topic</th></tr></thead><tbody><tr><td>Merge request opened</td><td><code>onMergeRequestOpened</code></td><td><code>gitlab.merge_request.open</code></td></tr><tr><td>Merge request reopened</td><td><code>onMergeRequestReopened</code></td><td><code>gitlab.merge_request.reopen</code></td></tr><tr><td>Merge request closed</td><td><code>onMergeRequestClosed</code></td><td><code>gitlab.merge_request.close</code></td></tr><tr><td>Merge request merged</td><td><code>onMergeRequestMerged</code></td><td><code>gitlab.merge_request.merge</code></td></tr><tr><td>Merge request approved</td><td><code>onMergeRequestReviewed</code></td><td><code>gitlab.merge_request.approved</code></td></tr><tr><td>Merge request unapproved</td><td><code>onMergeRequestReviewed</code></td><td><code>gitlab.merge_request.unapproved</code></td></tr><tr><td>MR individual approval</td><td><code>onMergeRequestIndividualReview</code></td><td><code>gitlab.merge_request.approval</code></td></tr><tr><td>Merge request updated</td><td><code>onMergeRequestUpdate</code></td><td><code>gitlab.merge_request.update</code></td></tr><tr><td>MR/issue comment</td><td><code>onCommentCreated</code></td><td><code>gitlab.note.created</code></td></tr><tr><td>Release created</td><td><code>onRelease</code></td><td><code>gitlab.release.create</code></td></tr><tr><td>Tag push</td><td><code>onGitLabTagPush</code></td><td><code>gitlab.tag_push</code></td></tr><tr><td>Push</td><td><code>onGitLabPush</code></td><td><code>gitlab.push</code></td></tr><tr><td>Wiki page event</td><td><code>onWikiPageEvent</code></td><td><code>gitlab.wiki_page</code></td></tr></tbody></table><h2 id="authentication" tabindex="-1">Authentication <a class="header-anchor" href="#authentication" aria-label="Permalink to &quot;Authentication&quot;">​</a></h2><p>GitLab uses <strong>personal access tokens</strong> per user. No instance-wide OAuth.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>!hookshot gitlab personaltoken &lt;instance-name&gt; &lt;access-token&gt;</span></span></code></pre></div><p>Check token status:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>!hookshot gitlab hastoken &lt;instance-name&gt;</span></span></code></pre></div><p>The <code>&lt;instance-name&gt;</code> must match an instance in your config.</p><h2 id="configuration" tabindex="-1">Configuration <a class="header-anchor" href="#configuration" aria-label="Permalink to &quot;Configuration&quot;">​</a></h2><div class="language-yaml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">gitlab</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  instances</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">    gitlab.com</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:                    </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Instance name (users reference this)</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">      url</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">https://gitlab.com</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">      # GitLab instance URL</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">    internal</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">      url</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">https://gitlab.internal.com</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  webhook</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">    secret</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;your-webhook-secret&quot;</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">  # Secret token for webhook verification</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">    publicUrl</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">https://hookshot.example.com/gitlab/webhook</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  userIdPrefix</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">_gitlab_</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">           # Optional: ghost user prefix</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  commentDebounceMs</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">5000</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">          # Optional: aggregate comments (ms)</span></span></code></pre></div><p>You must list all GitLab instances users will connect to. The <code>publicUrl</code> is where GitLab sends webhooks — must end with <code>/gitlab/webhook</code>.</p><p>The <code>secret</code> is used as the &quot;Secret token&quot; when adding webhooks in GitLab project settings.</p><h2 id="setup" tabindex="-1">Setup <a class="header-anchor" href="#setup" aria-label="Permalink to &quot;Setup&quot;">​</a></h2><h3 id="operator-configure-gitlab-in-hookshot" tabindex="-1">Operator: Configure GitLab in hookshot <a class="header-anchor" href="#operator-configure-gitlab-in-hookshot" aria-label="Permalink to &quot;Operator: Configure GitLab in hookshot&quot;">​</a></h3><ol><li>Add the <code>gitlab</code> section to config.yml (see above)</li><li>Ensure the webhook listener is accessible at the <code>publicUrl</code></li></ol><h3 id="user-connect-a-room-to-a-gitlab-project" tabindex="-1">User: Connect a room to a GitLab project <a class="header-anchor" href="#user-connect-a-room-to-a-gitlab-project" aria-label="Permalink to &quot;User: Connect a room to a GitLab project&quot;">​</a></h3><ol><li>Authenticate: <code>!hookshot gitlab personaltoken gitlab.com &lt;your-token&gt;</code></li><li>Connect: <code>!hookshot gitlab project &lt;project-url&gt;</code></li><li>Or use the widget UI in your Matrix client</li></ol><h3 id="gitlab-webhook-setup" tabindex="-1">GitLab webhook setup <a class="header-anchor" href="#gitlab-webhook-setup" aria-label="Permalink to &quot;GitLab webhook setup&quot;">​</a></h3><p>Add a webhook in GitLab: Project → Settings → Webhooks:</p><ul><li><strong>URL</strong>: your hookshot <code>publicUrl</code> (e.g., <code>https://hookshot.example.com/gitlab/webhook</code>)</li><li><strong>Secret token</strong>: the <code>webhook.secret</code> from your config</li><li><strong>Events</strong>: merge request, push, tag push, issue, note, release, wiki page</li></ul><h2 id="connection-options" tabindex="-1">Connection options <a class="header-anchor" href="#connection-options" aria-label="Permalink to &quot;Connection options&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Option</th><th>Type</th><th>Default</th><th>Description</th></tr></thead><tbody><tr><td><code>instance</code></td><td>string</td><td>required</td><td>GitLab instance name (from config)</td></tr><tr><td><code>path</code></td><td>string</td><td>required</td><td>Project path (e.g., <code>org/repo</code>)</td></tr><tr><td><code>enableHooks</code></td><td>string[]</td><td>14 defaults</td><td>Which events to receive</td></tr><tr><td><code>includeCommentBody</code></td><td>boolean</td><td>false</td><td>Include comment text in notifications</td></tr><tr><td><code>pushTagsRegex</code></td><td>string</td><td>all</td><td>Regex filter for tag push events</td></tr><tr><td><code>includingLabels</code></td><td>string[]</td><td>all</td><td>Only show events with these labels</td></tr><tr><td><code>excludingLabels</code></td><td>string[]</td><td>none</td><td>Hide events with these labels</td></tr></tbody></table><h3 id="default-enabled-events" tabindex="-1">Default enabled events <a class="header-anchor" href="#default-enabled-events" aria-label="Permalink to &quot;Default enabled events&quot;">​</a></h3><p><code>merge_request.open</code>, <code>merge_request.close</code>, <code>merge_request.merge</code>, <code>merge_request.reopen</code>, <code>merge_request.review</code>, <code>merge_request.review.individual</code>, <code>merge_request.ready_for_review</code>, <code>merge_request.review.comments</code>, <code>merge_request</code>, <code>tag_push</code>, <code>push</code>, <code>wiki</code>, <code>release</code>, <code>release.created</code></p><h2 id="bot-commands" tabindex="-1">Bot commands <a class="header-anchor" href="#bot-commands" aria-label="Permalink to &quot;Bot commands&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Command</th><th>Required args</th><th>Optional args</th><th>Description</th></tr></thead><tbody><tr><td><code>!gl create &lt;title&gt;</code></td><td><code>title</code></td><td><code>description</code>, <code>labels</code></td><td>Create an issue</td></tr><tr><td><code>!gl create-confidential &lt;title&gt;</code></td><td><code>title</code></td><td><code>description</code>, <code>labels</code></td><td>Create a confidential issue</td></tr><tr><td><code>!gl close &lt;number&gt;</code></td><td><code>number</code></td><td><code>comment</code></td><td>Close an issue</td></tr></tbody></table><h2 id="limitations" tabindex="-1">Limitations <a class="header-anchor" href="#limitations" aria-label="Permalink to &quot;Limitations&quot;">​</a></h2><ul><li>GitLab&#39;s webhook test button sends payloads without an <code>action</code> field — test events won&#39;t show up in rooms (but will appear in hookshot logs)</li><li>No OAuth flow — each user must provide their own personal access token</li><li>Comment debouncing (default 5s) aggregates rapid comments into one message</li><li>Legacy webhook path <code>/</code> is deprecated — use <code>/gitlab/webhook</code></li><li>No SDK used — hookshot calls the GitLab API v4 directly via HTTP</li></ul><h2 id="upstream-references" tabindex="-1">Upstream references <a class="header-anchor" href="#upstream-references" aria-label="Permalink to &quot;Upstream references&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Topic</th><th>URL</th></tr></thead><tbody><tr><td>GitLab webhooks</td><td><a href="https://docs.gitlab.com/ee/user/project/integrations/webhooks.html" target="_blank" rel="noreferrer">docs.gitlab.com/webhooks</a></td></tr><tr><td>Personal access tokens</td><td><a href="https://docs.gitlab.com/ee/user/profile/personal_access_tokens.html" target="_blank" rel="noreferrer">docs.gitlab.com/tokens</a></td></tr><tr><td>API v4</td><td><a href="https://docs.gitlab.com/ee/api/rest/" target="_blank" rel="noreferrer">docs.gitlab.com/api</a></td></tr></tbody></table><h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><p><strong>Concepts:</strong> <a href="./../understand/event-lifecycle">Event Lifecycle</a> · <a href="./../understand/integration-model">Integration Model</a> · <a href="./../understand/trust-and-boundaries">Trust and Boundaries</a></p><p><strong>Integrations:</strong> <a href="./overview">Overview</a> · <a href="./github">GitHub</a> — Similar integration · <a href="./jira">JIRA</a></p><p><strong>Reference:</strong> <a href="./../reference/bot-commands#gitlab-repository-commands">Bot Commands: GitLab</a> · <a href="./../reference/event-types">Event Types</a></p><p><strong>Operator:</strong> <a href="./../guides/operator/configuration">Configuration</a> · <a href="./../guides/operator/hardening">Hardening</a></p><p><strong>Troubleshooting:</strong> <a href="./../troubleshooting/webhooks-not-arriving">Webhooks Not Arriving</a> · <a href="./../troubleshooting/authentication#check-2-is-the-service-configured-for-oauth">Authentication</a> · <a href="./../troubleshooting/connection-issues">Connection Issues</a></p>`,42)])])}const u=t(i,[["render",d]]);export{g as __pageData,u as default};
